-- Справочник кодов ЕНС ТРУ, подлежащих изъятию из национального режима (закупка только у
-- отечественных товаропроизводителей / из реестра доверенного ПО). Источник: goszakup.gov.kz,
-- выгрузка на 01.10.2026. Отдельная база от crm_ens_tru_codes — у этой проверки свой справочник
-- и свой RPC, доступ только внутри приложения (не публичная страница).

CREATE TABLE IF NOT EXISTS public.crm_ens_tru_national_exemption_codes (
  code text PRIMARY KEY,
  name text NOT NULL,
  characteristic text NOT NULL DEFAULT '',
  industry text NOT NULL,
  basis text NOT NULL DEFAULT '',
  valid_until text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS crm_ens_tru_national_exemption_codes_industry_idx
  ON public.crm_ens_tru_national_exemption_codes (industry);

ALTER TABLE public.crm_ens_tru_national_exemption_codes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS crm_ens_tru_national_exemption_codes_manager_select ON public.crm_ens_tru_national_exemption_codes;
CREATE POLICY crm_ens_tru_national_exemption_codes_manager_select ON public.crm_ens_tru_national_exemption_codes
  FOR SELECT TO authenticated
  USING (NOT public.is_admin());

DROP POLICY IF EXISTS crm_ens_tru_national_exemption_codes_admin_write ON public.crm_ens_tru_national_exemption_codes;
CREATE POLICY crm_ens_tru_national_exemption_codes_admin_write ON public.crm_ens_tru_national_exemption_codes
  FOR ALL TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

GRANT SELECT ON TABLE public.crm_ens_tru_national_exemption_codes TO authenticated;

CREATE OR REPLACE FUNCTION public.check_ens_tru_national_exemption_codes(p_codes text[])
RETURNS TABLE (
  input_code text,
  found boolean,
  name text,
  characteristic text,
  industry text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_code text;
  v_norm text;
  v_seen text[] := ARRAY[]::text[];
  v_row public.crm_ens_tru_national_exemption_codes%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '28000';
  END IF;
  IF public.is_admin() THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_codes IS NULL OR array_length(p_codes, 1) IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_code IN ARRAY p_codes LOOP
    v_norm := public.normalize_ens_tru_code(v_code);
    IF v_norm IS NULL THEN
      CONTINUE;
    END IF;
    IF v_norm = ANY (v_seen) THEN
      CONTINUE;
    END IF;
    v_seen := array_append(v_seen, v_norm);

    SELECT * INTO v_row FROM public.crm_ens_tru_national_exemption_codes e WHERE e.code = v_norm;

    IF FOUND THEN
      RETURN QUERY SELECT v_norm, true, v_row.name, v_row.characteristic, v_row.industry;
    ELSE
      RETURN QUERY SELECT v_norm, false, NULL::text, NULL::text, NULL::text;
    END IF;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.check_ens_tru_national_exemption_codes(text[]) TO authenticated;

ON CONFLICT (code) DO UPDATE SET
  name = EXCLUDED.name,
  characteristic = EXCLUDED.characteristic,
  industry = EXCLUDED.industry,
  basis = EXCLUDED.basis,
  valid_until = EXCLUDED.valid_until;
